"use client";

import { Megaphone, Pin, Plus, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";

import { NoticesFilter } from "@/components/admin/notices-filter";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";

type Notice = {
  _id: string;
  title: string;
  excerpt: string;
  body: string;
  status: "draft" | "published";
  audience: string;
  pinned: boolean;
  publishedAt?: string;
};

const blank = {
  title: "",
  excerpt: "",
  body: "",
  audience: "all",
  pinned: false,
  status: "draft",
};

export function NoticesTable() {
  const [notices, setNotices] = useState<Notice[]>([]);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("");
  const [editing, setEditing] = useState<Notice | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState(blank);
  const [loading, setLoading] = useState(true);

  async function load() {
    setLoading(true);
    const query = new URLSearchParams({ search, status });
    const response = await fetch(`/api/admin/notices?${query}`);
    const result = (await response.json()) as { data?: { notices?: Notice[] } };
    setNotices(result.data?.notices ?? []);
    setLoading(false);
  }

  useEffect(() => {
    void load();
  }, [search, status]);

  function openEditor(notice?: Notice) {
    setEditing(notice ?? null);
    setModalOpen(true);
    setForm(
      notice
        ? {
            title: notice.title,
            excerpt: notice.excerpt,
            body: notice.body,
            audience: notice.audience,
            pinned: notice.pinned,
            status: notice.status,
          }
        : blank,
    );
  }

  async function save() {
    const endpoint = editing
      ? `/api/admin/notices/${editing._id}`
      : "/api/admin/notices";
    await fetch(endpoint, {
      method: editing ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    setEditing(null);
    setModalOpen(false);
    const open = () => openEditor();
    window.addEventListener("open-notice-editor", open);
    return () => window.removeEventListener("open-notice-editor", open);
  }

  async function remove(id: string) {
    if (window.confirm("Delete this notice?")) {
      await fetch(`/api/admin/notices/${id}`, { method: "DELETE" });
      await load();
    }
  }

  return (
    <>
      <div className="mt-5 flex justify-end">
        <button
          type="button"
          onClick={() => openEditor()}
          className="cursor-pointer rounded-md bg-primary px-4 py-2 text-sm text-cream"
        >
          New notice
        </button>
      </div>
      <NoticesFilter
        search={search}
        status={status}
        onSearch={setSearch}
        onStatus={setStatus}
        onClear={() => {
          setSearch("");
          setStatus("");
        }}
      />
      <div className="mt-5 overflow-hidden rounded-lg border border-border bg-card">
        {loading ? (
          <p className="p-8 text-sm text-muted">Loading notices...</p>
        ) : notices.length === 0 ? (
          <div className="p-10 text-center">
            <Megaphone className="mx-auto text-muted" size={36} />
            <p className="mt-3 text-sm text-muted">No notices yet.</p>
            <button
              type="button"
              onClick={() => openEditor()}
              className="mt-4 cursor-pointer text-sm text-accent"
            >
              Create the first notice
            </button>
          </div>
        ) : (
          notices.map((notice) => (
            <div
              key={notice._id}
              className="flex flex-col gap-3 border-b border-border p-5 last:border-0 md:flex-row md:items-center md:justify-between"
            >
              <button
                type="button"
                onClick={() => openEditor(notice)}
                className="cursor-pointer text-left"
              >
                <p className="font-medium text-primary">{notice.title}</p>
                <p className="mt-1 text-sm text-muted">{notice.excerpt}</p>
              </button>
              <div className="flex items-center gap-2">
                <Badge
                  className={
                    notice.status === "published"
                      ? "border-emerald-600/30 text-emerald-700"
                      : "text-muted"
                  }
                >
                  {notice.status}
                </Badge>
                {notice.pinned ? (
                  <Pin size={16} className="text-accent" />
                ) : null}
                <button
                  type="button"
                  aria-label="Delete notice"
                  onClick={() => remove(notice._id)}
                  className="cursor-pointer p-2 text-red-600"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          ))
        )}
      </div>
      {modalOpen ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-primary-dark/70 p-4">
          <div className="w-full max-w-xl rounded-lg border border-border bg-card p-6">
            <h2 className="font-heading text-xl font-bold text-primary">
              {editing ? "Edit notice" : "New notice"}
            </h2>
            <div className="mt-5 space-y-3">
              <Input
                placeholder="Title"
                value={form.title}
                onChange={(event) =>
                  setForm({ ...form, title: event.target.value })
                }
              />
              <Input
                placeholder="Excerpt"
                value={form.excerpt}
                onChange={(event) =>
                  setForm({ ...form, excerpt: event.target.value })
                }
              />
              <Textarea
                rows={8}
                placeholder="Body"
                value={form.body}
                onChange={(event) =>
                  setForm({ ...form, body: event.target.value })
                }
              />
              <Select
                value={form.audience}
                onChange={(event) =>
                  setForm({ ...form, audience: event.target.value })
                }
              >
                <option value="all">All</option>
                <option value="students">Students</option>
                <option value="university">University</option>
                <option value="other">Other</option>
              </Select>
              <Select
                value={form.status}
                onChange={(event) =>
                  setForm({ ...form, status: event.target.value })
                }
              >
                <option value="draft">Draft</option>
                <option value="published">Published</option>
              </Select>
              <label className="flex cursor-pointer items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  checked={form.pinned}
                  onChange={(event) =>
                    setForm({ ...form, pinned: event.target.checked })
                  }
                />
                Pinned
              </label>
            </div>
            <div className="mt-6 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => {
                  setEditing(null);
                  setModalOpen(false);
                  setForm(blank);
                }}
                className="cursor-pointer px-4 text-sm text-muted"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={save}
                className="inline-flex cursor-pointer items-center gap-2 rounded-md bg-primary px-4 py-2 text-sm text-cream"
              >
                <Plus size={16} />
                Save
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}
